BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Lease term determination with renewal options
(2, 'Leases', 'Under ASC 842, how is the lease term determined when a lease contains renewal options?', '["The lease term includes only the noncancelable period regardless of renewal options", "The lease term includes the noncancelable period plus any renewal periods the lessee is reasonably certain to exercise", "The lease term always includes all available renewal periods", "The lease term is the shorter of the noncancelable period or the asset''s economic life"]'::jsonb, 1, 'ASC 842-10-30-1 defines the lease term as the noncancelable period plus periods covered by renewal options the lessee is reasonably certain to exercise. The term also includes periods covered by termination options the lessee is reasonably certain not to exercise. Unlike choice A suggests, renewal options are not automatically excluded — they are included when exercise is reasonably certain based on economic factors.', 'easy', 1),

-- Q2: medium / L2 — Variable lease payments based on usage excluded from liability
(2, 'Leases', 'Westbrook Inc. enters a 4-year equipment lease with fixed annual payments of $30,000 plus a variable payment equal to $0.10 per unit produced. In Year 1, Westbrook produces 200,000 units. Under ASC 842, how should the variable payment be treated?', '["Include the $20,000 variable payment in the initial lease liability measurement", "Exclude the variable payment from the lease liability and recognize $20,000 as expense when incurred", "Capitalize the $20,000 as an addition to the ROU asset", "Estimate total variable payments over the lease term and include them in the lease liability"]'::jsonb, 1, 'ASC 842-10-30-5 requires that variable lease payments based on usage or performance (e.g., per-unit charges) be excluded from the lease liability and recognized as expense in the period incurred. Only fixed payments and variable payments tied to an index or rate are included in the liability measurement. Choice A incorrectly treats usage-based payments as part of the initial liability.', 'medium', 2),

-- Q3: medium / L3 — Embedded lease identification
(2, 'Leases', 'Parkfield Corp. enters a 3-year contract with a data center provider for dedicated use of a specific server rack. Parkfield controls when and how the server rack operates and the provider cannot substitute the equipment. Under ASC 842, how should Parkfield evaluate this arrangement?', '["The contract is a service arrangement because Parkfield does not hold title to the server rack", "The contract contains an embedded lease because Parkfield has the right to control the use of an identified asset", "The contract is a service arrangement because data center contracts are excluded from ASC 842", "The contract contains an embedded lease only if Parkfield has the option to purchase the equipment"]'::jsonb, 1, 'ASC 842-10-15-2 states that a contract contains a lease if it conveys the right to control the use of an identified asset for a period of time in exchange for consideration. Control exists when the customer has the right to obtain substantially all economic benefits from the asset and direct its use. Because Parkfield controls a specific, non-substitutable asset, the contract contains an embedded lease. Choice A incorrectly equates ownership with lease identification.', 'medium', 3),

-- Q4: easy / L2 — Lease incentive effect on operating lease expense
(2, 'Leases', 'Oakmont LLC enters a 5-year operating lease with annual payments of $48,000. The lessor provides a $10,000 tenant improvement allowance at commencement. Under ASC 842, what is Oakmont''s annual straight-line lease expense?', '["$46,000", "$48,000", "$50,000", "$38,000"]'::jsonb, 0, 'Under ASC 842-10-25-6, operating lease expense is recognized on a straight-line basis over the lease term. Total payments are $48,000 x 5 = $240,000, less the $10,000 lease incentive = $230,000 net. Annual straight-line expense = $230,000 / 5 = $46,000. Choice B ignores the incentive entirely, but lease incentives reduce the total cost allocated over the term.', 'easy', 2),

-- Q5: easy / L1 — Lease commencement vs inception date
(2, 'Leases', 'Under ASC 842, what is the difference between the lease commencement date and the lease inception date?', '["There is no difference; the terms are interchangeable", "The inception date is when the agreement is signed; the commencement date is when the lessor makes the asset available to the lessee", "The commencement date is when the agreement is signed; the inception date is when the first payment is made", "The inception date is when the lessee takes physical possession; the commencement date is when the first payment is due"]'::jsonb, 1, 'ASC 842-10-20 distinguishes inception (the earlier of the date of the lease agreement or a commitment by the parties to the principal terms) from commencement (the date the lessor makes the underlying asset available for use by the lessee). Classification is assessed at inception, but measurement occurs at commencement. Choice A incorrectly treats the two dates as identical.', 'easy', 1),

-- Q6: medium / L2 — Finance lease Year 2 interest expense calculation
(2, 'Leases', 'Haverford Corp. enters a 4-year finance lease on January 1, Year 1, with annual payments of $60,000 due at year-end. The discount rate is 7%, and the initial lease liability is $203,040. Interest expense in Year 1 is $14,213. What is the interest expense in Year 2?', '["$14,213", "$11,006", "$10,994", "$11,008"]'::jsonb, 3, 'Under ASC 842-20-35-1, the lessee recognizes interest on the lease liability using the effective interest method. Year 1 ending liability = $203,040 + $14,213 − $60,000 = $157,253. Year 2 interest = $157,253 × 7% = $11,008 (rounded). Using exact figures: Year 1 interest = $203,040 × 0.07 = $14,212.80, ending balance = $157,252.80, Year 2 interest = $157,252.80 × 0.07 = $11,007.70 ≈ $11,008. Choice A incorrectly applies a straight-line interest pattern rather than the declining effective interest method.', 'medium', 2),

-- Q7: medium / L2 — Non-lease component allocation
(2, 'Leases', 'Ridgeway Inc. signs a 3-year office lease with total annual payments of $90,000 covering both the office space ($72,000 standalone price) and maintenance services ($18,000 standalone price). Ridgeway does not elect the practical expedient. Under ASC 842, what amount is included in the lease liability calculation?', '["$90,000 annually", "$72,000 annually", "$18,000 annually", "$54,000 annually"]'::jsonb, 1, 'ASC 842-10-15-28 requires lessees to allocate consideration between lease and non-lease components based on relative standalone prices unless the practical expedient to combine them is elected. The lease component is $72,000/$90,000 = 80% of total consideration. Only the $72,000 lease component is included in the lease liability. Choice A incorrectly includes the maintenance non-lease component in the liability.', 'medium', 2),

-- Q8: medium / L2 — Operating lease ROU asset as balancing figure
(2, 'Leases', 'Brennan Corp. has a 5-year operating lease. At the beginning of Year 2, the lease liability balance is $168,000 and the ROU asset balance is $172,000. The annual straight-line lease expense is $50,000, the annual payment is $50,000, and the discount rate is 6%. What is the ROU asset balance at the end of Year 2?', '["$132,080", "$128,000", "$122,000", "$134,080"]'::jsonb, 0, 'Under ASC 842-20-35-8, for an operating lease the ROU asset is adjusted as a balancing figure: ROU reduction = Straight-line expense − Interest on liability. Year 2 interest = $168,000 × 6% = $10,080. ROU reduction = $50,000 − $10,080 = $39,920. Ending ROU = $172,000 − $39,920 = $132,080. Choice B incorrectly reduces the ROU by the full payment amount rather than by the difference between straight-line expense and interest.', 'medium', 2),

-- Q9: hard / L4 — Sale-leaseback with finance leaseback = failed sale
(2, 'Leases', 'Glenmore Corp. sells equipment with a carrying amount of $300,000 to Pinnacle LLC for $450,000 (fair value) and simultaneously leases it back for 10 years. The equipment has a 12-year remaining life, the PV of lease payments is 92% of fair value, and the lease does not transfer ownership. Under ASC 842, how should Glenmore account for this transaction?', '["Recognize a $150,000 gain and record an ROU asset and lease liability for the leaseback", "Recognize the cash received as a financing obligation and continue to depreciate the equipment", "Recognize a gain limited to the rights transferred and defer the remainder", "Derecognize the equipment and recognize a partial gain based on the 2-year residual transferred"]'::jsonb, 1, 'ASC 842-40-25-1 through 25-4 requires the seller-lessee to first determine whether the transfer qualifies as a sale under ASC 606, then assess the leaseback classification. Because the PV of lease payments (92%) exceeds substantially all (≥90%) of fair value, the leaseback is a finance lease. Per ASC 842-40-25-4, when the leaseback would be classified as a finance lease, the transaction fails sale treatment regardless of whether control transferred. Glenmore records cash as a financing obligation and keeps the asset. Choice A incorrectly treats it as a completed sale.', 'hard', 4),

-- Q10: easy / L1 — Lessor initial direct costs definition
(2, 'Leases', 'Under ASC 842, what are initial direct costs in a lease arrangement?', '["All costs the lessor incurs to negotiate and arrange a lease, including allocated overhead", "Incremental costs of a lease that would not have been incurred if the lease had not been obtained", "Legal fees, commissions, and allocated internal costs associated with lease origination", "Any costs incurred by either party before the lease commencement date"]'::jsonb, 1, 'ASC 842-10-30-9 defines initial direct costs as incremental costs of a lease that would not have been incurred if the lease had not been obtained. This narrow definition excludes allocated overhead, legal fees for drafting, and other non-incremental costs. Choice A is incorrect because allocated overhead is explicitly excluded from the definition of initial direct costs under ASC 842.', 'easy', 1),

-- Q11: easy / L1 — Lessee balance sheet presentation current vs noncurrent
(2, 'Leases', 'Under ASC 842, how should a lessee present the lease liability on its classified balance sheet?', '["Entirely as a noncurrent liability", "Entirely as a current liability", "Separated into current and noncurrent portions based on payment timing", "As a contra-asset offsetting the ROU asset"]'::jsonb, 2, 'ASC 842-20-45-1 requires the lessee to present the lease liability in the balance sheet separated into current and noncurrent portions, similar to other financial liabilities. The current portion represents lease payments due within one year. Choice A is incorrect because the portion due within one year must be classified as a current liability.', 'easy', 1),

-- Q12: medium / L2 — Lessor net investment components
(2, 'Leases', 'Summerlin Inc. enters a sales-type lease for equipment with a fair value of $500,000. The 8-year lease requires annual payments of $72,000 at year-end, and the estimated unguaranteed residual value at lease end is $40,000. The implicit rate is 5%. Under ASC 842, what components make up the lessor''s net investment in the lease at commencement?', '["The PV of lease payments only", "The PV of lease payments plus the PV of any guaranteed residual value", "The PV of lease payments plus the PV of the unguaranteed residual value", "The undiscounted total of all lease payments plus residual value"]'::jsonb, 2, 'ASC 842-30-30-1 defines the lessor''s net investment as the lease receivable (PV of lease payments plus any guaranteed residual) plus the unguaranteed residual asset (PV of unguaranteed residual). Choice A is wrong because it omits the residual component entirely. Choice B is a common error — it includes only the guaranteed residual but ignores the unguaranteed residual asset, which is a separate component of the net investment.', 'medium', 2),

-- Q13: medium / L2 — Practical expedient to combine lease and non-lease components
(2, 'Leases', 'Wellspring Corp. leases a building with total annual payments of $120,000 covering both space rental and common area maintenance (CAM). Wellspring elects the practical expedient under ASC 842 to not separate lease and non-lease components. Under ASC 842, how should Wellspring account for the combined payments?', '["Allocate payments based on relative standalone prices and include only the lease portion in the liability", "Treat the entire $120,000 as a single lease component for measurement purposes", "Exclude the CAM portion and include only an estimated rental amount in the liability", "Record the CAM portion as a separate service liability outside the lease"]'::jsonb, 1, 'ASC 842-10-15-37 provides a practical expedient allowing lessees to elect, by class of underlying asset, to account for lease and non-lease components as a single lease component. When elected, the entire consideration ($120,000) is included in the lease liability measurement. Choice A describes the treatment when the practical expedient is NOT elected. The expedient simplifies accounting by avoiding the allocation.', 'medium', 2),

-- Q14: medium / L3 — Lessee reassessment triggers for lease term
(2, 'Leases', 'Fieldstone Inc. has a 5-year operating lease with two 3-year renewal options. At commencement, Fieldstone determined it was not reasonably certain to exercise either option. In Year 3, Fieldstone installs $500,000 of leasehold improvements with a 7-year useful life. Under ASC 842, what is the most likely accounting effect?', '["No effect because the lease term was established at commencement and cannot change", "Fieldstone must reassess the lease term and will likely include the renewal periods, remeasuring the lease liability", "Fieldstone should amortize the leasehold improvements over the remaining 2-year lease term only", "Fieldstone should negotiate a new lease to match the improvement useful life"]'::jsonb, 1, 'ASC 842-10-35-1 requires reassessment of the lease term when a significant event or change in circumstances occurs that is within the lessee''s control and affects whether exercise of an option is reasonably certain. A significant leasehold improvement investment creates an economic incentive to renew, triggering reassessment. The lessee would likely conclude renewal is now reasonably certain and remeasure the liability at a revised discount rate. Choice A incorrectly states the lease term is permanently fixed.', 'medium', 3),

-- Q15: hard / L4 — Sale-leaseback gain allocation between rights transferred and retained
(2, 'Leases', 'Alderman Corp. sells a building with a carrying amount of $600,000 to Whitfield LLC for $900,000, its fair value, and leases it back for 5 years under an operating lease. The building has a 20-year remaining useful life. Under ASC 842, how much gain should Alderman recognize at the transaction date?', '["$300,000", "$225,000", "$75,000", "$0"]'::jsonb, 1, 'Under ASC 842-40-25-4, when the sale-leaseback qualifies as a sale (the leaseback is operating, not finance), the seller-lessee recognizes gain only on the rights transferred to the buyer — the portion NOT leased back. The rights retained = 5/20 = 25% of the asset''s value; rights transferred = 75%. Total gain = $900,000 − $600,000 = $300,000. Gain recognized = $300,000 × 75% = $225,000. The remaining $75,000 adjusts the ROU asset. Choice A incorrectly recognizes the full gain.', 'hard', 4),

-- Q16: medium / L2 — Finance lease cash flow classification
(2, 'Leases', 'Grayson Corp. has a 5-year finance lease with annual payments of $80,000. In Year 1, interest expense is $24,000 and principal reduction is $56,000. Under ASC 842, how should Grayson classify the $80,000 payment on the statement of cash flows?', '["$80,000 as operating activities", "$80,000 as financing activities", "$24,000 as operating activities and $56,000 as financing activities", "$56,000 as operating activities and $24,000 as financing activities"]'::jsonb, 2, 'ASC 842-20-45-4 requires that for finance leases, the interest portion of lease payments be classified as operating activities (consistent with other interest payments) and the principal portion as financing activities. This split mirrors debt service classification. Choice A applies only to operating leases, where the entire payment is classified as operating. Choice B incorrectly treats the full payment as financing.', 'medium', 2),

-- Q17: easy / L1 — ROU asset impairment applicability
(2, 'Leases', 'Under ASC 842, is a lessee''s right-of-use asset subject to impairment testing?', '["No, ROU assets are excluded from impairment testing under all circumstances", "Yes, ROU assets are tested for impairment under ASC 360 (long-lived assets)", "Yes, but only ROU assets from finance leases are subject to impairment", "No, the lease liability adjustment mechanism replaces impairment testing"]'::jsonb, 1, 'ASC 842-20-35-9 states that the ROU asset is subject to impairment testing in accordance with ASC 360-10 (Property, Plant, and Equipment — Impairment or Disposal of Long-Lived Assets). This applies to ROU assets from both finance and operating leases. Choice C incorrectly limits impairment to finance leases only. If indicators of impairment exist, the lessee must assess recoverability.', 'easy', 1),

-- Q18: easy / L1 — Operating lease cash flow classification
(2, 'Leases', 'Under ASC 842, how are lease payments for an operating lease classified on the lessee''s statement of cash flows?', '["Entirely as financing activities", "Entirely as operating activities", "Split between operating and financing activities", "Entirely as investing activities"]'::jsonb, 1, 'ASC 842-20-45-5 requires operating lease payments to be classified entirely within operating activities on the statement of cash flows. This contrasts with finance leases, where payments are split between operating (interest) and financing (principal). Choice A describes neither operating nor finance lease treatment. The operating classification is consistent with the expense being reported within operations.', 'easy', 1),

-- Q19: hard / L3 — Lessor selling loss in direct financing lease
(2, 'Leases', 'Redmond Corp. leases equipment with a carrying amount of $280,000 and a fair value of $250,000. The lease does not meet any of the five transfer criteria, but the PV of lease payments plus PV of the residual value equals substantially all of the fair value. Collection is probable. Under ASC 842, how should Redmond account for the $30,000 difference at commencement?', '["Defer the $30,000 loss and recognize it over the lease term as a reduction of interest income", "Recognize a $30,000 selling loss immediately in the income statement", "Record the net investment at $280,000 (carrying amount) with no loss recognition", "Reduce the residual asset by $30,000 and recognize no immediate loss"]'::jsonb, 1, 'Under ASC 842-30-25-1, this lease qualifies as a direct financing lease (no transfer criteria met, PV of payments plus residual ≈ fair value, collection probable). ASC 842-30-25-7 requires that selling losses in a direct financing lease be recognized immediately at commencement. This asymmetric treatment — where selling profit is deferred but selling loss is recognized immediately — reflects the conservatism principle. Choice A incorrectly applies the deferral treatment that applies only to selling profits in direct financing leases.', 'hard', 3),

-- Q20: medium / L2 — Lease modification not a separate lease — remeasurement
(2, 'Leases', 'Carrington Inc. has a 6-year operating lease with a remaining term of 4 years and a current lease liability of $320,000. The lease is modified to add a parking area at a rate that is below its standalone price. The revised discount rate is 5%, and the modified total remaining payments have a PV of $380,000. Under ASC 842, how should Carrington account for this modification?', '["Account for the parking area as a separate lease independent of the original lease", "Remeasure the lease liability to $380,000 and adjust the ROU asset for the $60,000 difference", "Continue recording the original lease unchanged and expense the parking area payments as incurred", "Recognize a $60,000 gain on lease modification"]'::jsonb, 1, 'ASC 842-10-25-8 requires that when a modification grants an additional right of use but the price is NOT commensurate with the standalone price, the modification is NOT treated as a separate lease. Instead, the lessee remeasures the lease liability at the revised discount rate and adjusts the ROU asset. The $60,000 increase ($380,000 − $320,000) increases the ROU asset. Choice A would apply only if the price were commensurate with standalone price.', 'medium', 2),

-- Q21: easy / L1 — Specialized asset criterion
(2, 'Leases', 'Under ASC 842, what does the "specialized nature" criterion mean for lessee lease classification?', '["The asset requires specialized maintenance during the lease term", "The underlying asset has no alternative use to the lessor at the end of the lease term due to its specialized design", "The lessee must employ specialized personnel to operate the asset", "The asset is manufactured by a single supplier"]'::jsonb, 1, 'ASC 842-10-25-2(e) states that a lease is classified as a finance lease if the underlying asset is of such a specialized nature that it is expected to have no alternative use to the lessor at the end of the lease term. This reflects the economic substance that the lessor has effectively transferred the entire value. Choice A confuses maintenance requirements with the classification criterion regarding the asset''s alternative use.', 'easy', 1),

-- Q22: easy / L1 — Lease liability discount rate hierarchy
(2, 'Leases', 'Under ASC 842, what discount rate does a lessee use to measure the lease liability?', '["The lessee''s weighted average cost of capital", "The rate implicit in the lease if readily determinable; otherwise, the lessee''s incremental borrowing rate", "The risk-free rate published by the Federal Reserve", "The lessor''s borrowing rate as disclosed in the lease agreement"]'::jsonb, 1, 'ASC 842-20-30-3 establishes a hierarchy: the lessee uses the rate implicit in the lease when it is readily determinable. If not readily determinable, the lessee uses its own incremental borrowing rate. As a practical expedient, private companies may use a risk-free rate, but this is not the default. Choice A is not part of the ASC 842 discount rate hierarchy for lease measurement.', 'easy', 1),

-- Q23: medium / L3 — Variable payments tied to CPI subsequent remeasurement
(2, 'Leases', 'Sterling Corp. has a 10-year operating lease with an initial annual payment of $50,000 that adjusts annually based on the Consumer Price Index (CPI). At commencement, the lease liability was measured using the initial CPI rate. In Year 3, the CPI increases by 4%, raising the payment to $54,080. Under ASC 842, when does Sterling remeasure the lease liability for the CPI change?', '["At each annual CPI adjustment date", "Only when another reassessment event (such as a modification) triggers remeasurement", "At the beginning of each fiscal year regardless of CPI changes", "Immediately when the CPI change is published"]'::jsonb, 1, 'ASC 842-10-35-4 states that variable payments based on an index or rate are included in the initial liability using the index at commencement. The liability is NOT remeasured solely because the index changes. Remeasurement occurs only when triggered by another event — such as a lease modification, reassessment of a renewal option, or change in amounts probable of being owed under a residual guarantee. Choice A incorrectly implies automatic remeasurement at each CPI reset.', 'medium', 3),

-- Q24: medium / L3 — Annuity due vs ordinary annuity effect on liability
(2, 'Leases', 'Waverly Inc. enters a 4-year finance lease with annual payments of $40,000. The discount rate is 6%. If payments are due at the beginning of each year (annuity due) rather than at the end (ordinary annuity), what effect does this have on the initial lease liability compared to year-end payments?', '["The initial lease liability is lower with beginning-of-year payments", "The initial lease liability is the same regardless of payment timing", "The initial lease liability is higher with beginning-of-year payments", "The initial lease liability is higher only if the discount rate exceeds 5%"]'::jsonb, 2, 'Under ASC 842-20-30-1, the lease liability equals the present value of future lease payments. An annuity due (payments at the beginning) has a higher PV than an ordinary annuity (payments at end) because each payment is discounted one fewer period. For example, with 4 payments of $40,000 at 6%: ordinary annuity PV factor = 3.4651 (liability = $138,604); annuity due PV factor = 3.6730 (liability = $146,920). Choice A reverses the relationship — earlier payments increase, not decrease, PV.', 'medium', 3),

-- Q25: medium / L3 — Lease classification change upon modification
(2, 'Leases', 'Harper Corp. has an operating lease for equipment with 3 years remaining. The lease is modified to extend the term by 5 years (total remaining: 8 years). The equipment has a remaining economic life of 9 years. Under ASC 842, what is the most likely classification effect?', '["The lease remains an operating lease because classification is locked at commencement", "The lease may be reclassified as a finance lease because the modified term (8/9 years = 89%) meets the major-part criterion", "The lease is automatically reclassified as a finance lease upon any term extension", "The modification must be treated as a new, separate lease regardless of classification"]'::jsonb, 1, 'ASC 842-10-25-15 requires the lessee to reassess lease classification when a modification is not treated as a separate lease. With 8 years remaining out of a 9-year economic life, the lease term represents approximately 89% of the remaining economic life, which meets the major-part criterion (≥75%). The lease would likely be reclassified as a finance lease. Choice A incorrectly states classification cannot change — modifications trigger reassessment.', 'medium', 3),

-- Q26: medium / L3 — Sublease classification using ROU asset remaining term
(2, 'Leases', 'Prescott Inc. has a 10-year head lease for office space with 6 years remaining. Prescott subleases the space to Dalton Corp. for 5 years at market rates. The sublease does not transfer ownership or contain a purchase option. Under ASC 842, how should Prescott classify the sublease?', '["Operating lease, because subleases cannot be classified as finance leases", "Finance lease, because the sublease term (5/6 years = 83%) is for the major part of the remaining ROU asset term", "Operating lease, because the sublease term is less than 75% of the original 10-year head lease", "Direct financing lease, because the sublease defers any profit"]'::jsonb, 1, 'ASC 842-10-25-2 requires the intermediate lessor (sublessor) to classify the sublease based on the right-of-use asset, not the underlying asset. The relevant economic life is the remaining head lease term (6 years), not the original term. The sublease term (5 years) is 83% of the remaining term, meeting the major-part criterion. Choice C incorrectly references the original 10-year head lease term rather than the remaining 6 years.', 'medium', 3),

-- Q27: hard / L4 — Lessor classification: direct financing vs operating when selling profit exists
(2, 'Leases', 'Cumberland Inc. leases manufacturing equipment with a carrying amount of $400,000 and a fair value of $460,000. The 7-year lease has annual payments of $74,000 at year-end, and the estimated unguaranteed residual is $30,000. None of the five transfer criteria are met. The PV of lease payments plus PV of the unguaranteed residual equals $460,000, and collection is probable. Under ASC 842, how should Cumberland classify this lease?', '["Sales-type lease because a selling profit exists at commencement", "Direct financing lease because the PV test is met and criteria are not met", "Operating lease because the selling profit disqualifies direct financing", "Direct financing lease with the selling profit recognized immediately"]'::jsonb, 2, 'ASC 842-30-25-3(b) adds a critical condition for direct financing classification: the lessor must NOT have a selling profit (i.e., fair value must not exceed carrying amount). Here, fair value ($460,000) exceeds carrying amount ($400,000), creating a selling profit that disqualifies direct financing. Since no transfer criteria are met either, the lease defaults to operating. Choice B is wrong because it ignores the no-selling-profit requirement. Choice A is wrong because sales-type requires at least one transfer criterion to be met.', 'hard', 4),

-- Q28: hard / L4 — Multi-element lease with variable and fixed components
(2, 'Leases', 'Langford Corp. enters a 6-year equipment lease with the following payment structure: fixed rent of $45,000/year, variable rent equal to 3% of annual revenue (Year 1 actual: $900,000), and annual maintenance of $8,000 (non-lease component at standalone price). Langford does not elect the practical expedient. The IBR is 5%, and the PV of an ordinary annuity at 5% for 6 years is 5.0757. What is Langford''s initial lease liability?', '["$268,977", "$228,408", "$269,091", "$309,091"]'::jsonb, 1, 'Under ASC 842-10-30-5, only fixed lease payments are included in the initial liability; variable payments based on revenue (a performance metric) are excluded. Non-lease components ($8,000 maintenance) are separated per ASC 842-10-15-28 when the practical expedient is not elected. Initial lease liability = $45,000 × 5.0757 = $228,408 (rounded). Choice A incorrectly includes the maintenance component ($53,000 × 5.0757 ≈ $269,013). Choice D adds estimated variable rent to the fixed payments.', 'hard', 4),

-- Q29: medium / L3 — Lease termination penalty and lease term assessment
(2, 'Leases', 'Stanton Corp. signs a 10-year office lease with a termination option exercisable in Year 5 subject to a penalty of $200,000. The remaining 5 years of rental payments total $500,000. At commencement, management considers it reasonably certain NOT to terminate because the penalty plus relocation costs exceed the benefits. Under ASC 842, what lease term should Stanton use?', '["5 years, because the termination option exists and must be assumed to be exercised", "10 years, because the lessee is reasonably certain not to exercise the termination option", "7.5 years, averaging the cancelable and noncancelable periods", "5 years plus the $200,000 penalty recognized as a liability at commencement"]'::jsonb, 1, 'ASC 842-10-55-22 through 55-24 provides that the lease term includes periods covered by a termination option that the lessee is reasonably certain NOT to exercise. When the economic penalty of termination (penalty payment plus relocation costs) exceeds the benefit of terminating, the lessee is reasonably certain to remain, and the full 10-year term is used. Choice A incorrectly assumes the termination option automatically shortens the term. The penalty itself is not separately recognized as a liability.', 'medium', 3),

-- Q30: hard / L4 — Related party lease at off-market terms
(2, 'Leases', 'Whitfield Corp. leases a warehouse from its parent company for $20,000/year for 5 years. Independent market rent for comparable space is $35,000/year. The warehouse has a remaining useful life of 20 years and a fair value of $400,000. Under ASC 842, how should Whitfield account for this related party lease?', '["Use the $35,000 market rate to measure the lease liability and recognize the $15,000 difference as a capital contribution", "Measure the lease liability using the stated $20,000 contractual payments, as ASC 842 requires use of legally enforceable terms", "Impute the $35,000 market rate and recognize the $15,000 annual difference as additional rent expense", "Disregard the lease and consolidate the warehouse on Whitfield''s balance sheet"]'::jsonb, 1, 'ASC 842-10-55-12 states that related party leases are accounted for based on the legally enforceable terms and conditions of the lease, similar to how other related party transactions are classified on the basis of their legal form. Even though the rent is below market, the lease liability is measured using the contractual $20,000 payments. Choice A incorrectly adjusts to market rate — ASC 842 does not require mark-to-market for related party leases (though separate entity financial statements must disclose the related party nature).', 'hard', 4)

;

COMMIT;
